package com.example.transaction.client.impl

import com.example.transaction.dto.BookingDates
import com.example.transaction.dto.BookingResponse
import com.example.transaction.exception.BookingApiException
import org.springframework.web.reactive.function.client.WebClient
import reactor.core.publisher.Mono
import spock.lang.Specification

class BookingWebClientImplSpec extends Specification {

    // ─── WebClient fluent-chain mocks ─────────────────────────────────────────
    WebClient.Builder webClientBuilder        = Mock()
    WebClient webClient                       = Mock()
    WebClient.RequestHeadersUriSpec  uriSpec  = Mock()
    WebClient.RequestHeadersSpec     headSpec = Mock()
    WebClient.ResponseSpec           respSpec = Mock()

    BookingWebClientImpl client

    static final String INJECTED_URL     = "https://restful-booker.herokuapp.com/booking/{id}"
    static final String INJECTED_MESSAGE = "ketoKet"

    def setup() {
        webClientBuilder.build() >> webClient
        client = new BookingWebClientImpl(webClientBuilder)
        // Inject @Value fields via Groovy direct private-field access
        client.@apiUrl       = INJECTED_URL
        client.@errorMessage = INJECTED_MESSAGE
    }

    // ─── Success path ──────────────────────────────────────────────────────────

    def "getBooking should return a fully populated BookingResponse on success"() {
        given: "the external API returns a complete booking payload"
        def dates    = new BookingDates("2018-01-01", "2019-01-01")
        def expected = new BookingResponse("Josh", "Allen", 111, true, dates, "super bowls")

        webClient.get()                       >> uriSpec
        uriSpec.uri(*_)                       >> headSpec
        headSpec.retrieve()                   >> respSpec
        respSpec.bodyToMono(BookingResponse)  >> Mono.just(expected)

        when:
        def result = client.getBooking(1)

        then: "every field in the response is correctly mapped"
        result.firstName              == "Josh"
        result.lastName               == "Allen"
        result.totalPrice             == 111
        result.depositPaid            == true
        result.bookingDates           != null
        result.bookingDates.checkIn   == "2018-01-01"
        result.bookingDates.checkOut  == "2019-01-01"
        result.additionalNeeds        == "super bowls"
    }

    // ─── URL injection ─────────────────────────────────────────────────────────

    def "getBooking should call the external API using the injected apiUrl as URI template"() {
        given: "stub the remainder of the WebClient chain"
        def dto = new BookingResponse("Josh", "Allen", 111, true,
                new BookingDates("2018-01-01", "2019-01-01"), "super bowls")

        webClient.get()                      >> uriSpec
        headSpec.retrieve()                  >> respSpec
        respSpec.bodyToMono(BookingResponse) >> Mono.just(dto)

        when:
        client.getBooking(42)

        then: "uri() is called exactly once with the injected URL template and the id as a varargs Object[]"
        1 * uriSpec.uri(INJECTED_URL, _ as Object[]) >> headSpec
    }

    def "apiUrl field holds the value injected from booking.api.url configuration"() {
        expect:
        client.@apiUrl == INJECTED_URL
    }

    // ─── Error-message injection ────────────────────────────────────────────────

    def "errorMessage field holds the value injected from booking.error.message configuration"() {
        expect:
        client.@errorMessage == INJECTED_MESSAGE
    }

    // ─── Error handling ────────────────────────────────────────────────────────

    def "getBooking should throw BookingApiException with the injected error message when Mono emits an error"() {
        given: "the Mono emits an error (simulating any upstream failure)"
        webClient.get()                      >> uriSpec
        uriSpec.uri(*_)                      >> headSpec
        headSpec.retrieve()                  >> respSpec
        respSpec.bodyToMono(BookingResponse) >> Mono.error(new RuntimeException("upstream 500"))

        when:
        client.getBooking(1)

        then: "BookingApiException is thrown carrying the configured error message"
        def ex = thrown(BookingApiException)
        ex.message == INJECTED_MESSAGE
    }

    def "getBooking should wrap the original cause inside BookingApiException on failure"() {
        given: "the Mono emits a specific cause"
        def cause = new RuntimeException("network timeout")
        webClient.get()                      >> uriSpec
        uriSpec.uri(*_)                      >> headSpec
        headSpec.retrieve()                  >> respSpec
        respSpec.bodyToMono(BookingResponse) >> Mono.error(cause)

        when:
        client.getBooking(99)

        then: "the original exception is preserved as the cause"
        def ex = thrown(BookingApiException)
        ex.cause == cause
    }

    def "getBooking should throw BookingApiException even when retrieve() itself throws synchronously"() {
        given: "retrieve() throws before a Mono is ever returned"
        webClient.get()  >> uriSpec
        uriSpec.uri(*_)  >> headSpec
        headSpec.retrieve() >> { throw new RuntimeException("connection refused") }

        when:
        client.getBooking(7)

        then:
        def ex = thrown(BookingApiException)
        ex.message == INJECTED_MESSAGE
    }
}

package com.example.transaction.client.impl

import com.example.transaction.dto.BookingDates
import com.example.transaction.dto.BookingResponse
import com.example.transaction.exception.BookingApiException
import org.springframework.web.reactive.function.client.WebClient
import org.springframework.web.reactive.function.client.WebClientResponseException
import reactor.core.publisher.Mono
import spock.lang.Specification

class BookingWebClientImplSpec extends Specification {

    // ─── WebClient fluent-chain mocks ─────────────────────────────────────────
    WebClient.Builder webClientBuilder        = Mock()
    WebClient webClient                       = Mock()
    WebClient.RequestHeadersUriSpec  uriSpec  = Mock()
    WebClient.RequestHeadersSpec     headSpec = Mock()
    WebClient.ResponseSpec           respSpec = Mock()

    BookingWebClientImpl client

    static final String INJECTED_URL     = "https://restful-booker.herokuapp.com/booking/{id}"
    static final String INJECTED_MESSAGE = "ketoKet"

    def setup() {
        webClientBuilder.build() >> webClient
        client = new BookingWebClientImpl(webClientBuilder)
        // Inject @Value fields via Groovy direct private-field access
        client.@apiUrl       = INJECTED_URL
        client.@errorMessage = INJECTED_MESSAGE
    }

    // ─── Success path ──────────────────────────────────────────────────────────

    def "getBooking should return a fully populated BookingResponse on success"() {
        given: "the external API returns a complete booking payload"
        def dates    = new BookingDates("2018-01-01", "2019-01-01")
        def expected = new BookingResponse("Josh", "Allen", 111, true, dates, "super bowls")

        webClient.get()                       >> uriSpec
        uriSpec.uri(*_)                       >> headSpec
        headSpec.retrieve()                   >> respSpec
        respSpec.bodyToMono(BookingResponse)  >> Mono.just(expected)

        when:
        def result = client.getBooking(1)

        then: "every field in the response is correctly mapped"
        result.firstName              == "Josh"
        result.lastName               == "Allen"
        result.totalPrice             == 111
        result.depositPaid            == true
        result.bookingDates           != null
        result.bookingDates.checkIn   == "2018-01-01"
        result.bookingDates.checkOut  == "2019-01-01"
        result.additionalNeeds        == "super bowls"
    }

    // ─── URL injection ─────────────────────────────────────────────────────────

    def "getBooking should call the external API using the injected apiUrl as URI template"() {
        given: "stub the remainder of the WebClient chain"
        def dto = new BookingResponse("Josh", "Allen", 111, true,
                new BookingDates("2018-01-01", "2019-01-01"), "super bowls")

        webClient.get()                      >> uriSpec
        headSpec.retrieve()                  >> respSpec
        respSpec.bodyToMono(BookingResponse) >> Mono.just(dto)

        when:
        client.getBooking(42)

        then: "uri() is called exactly once with the injected URL template and the id as a varargs Object[]"
        1 * uriSpec.uri(INJECTED_URL, _ as Object[]) >> headSpec
    }

    def "apiUrl field holds the value injected from booking.api.url configuration"() {
        expect:
        client.@apiUrl == INJECTED_URL
    }

    // ─── Error-message injection ────────────────────────────────────────────────

    def "errorMessage field holds the value injected from booking.error.message configuration"() {
        expect:
        client.@errorMessage == INJECTED_MESSAGE
    }

    // ─── Error handling ────────────────────────────────────────────────────────

    def "getBooking should throw BookingApiException with the injected error message when Mono emits an error"() {
        given: "the Mono emits an error (simulating any upstream failure)"
        webClient.get()                      >> uriSpec
        uriSpec.uri(*_)                      >> headSpec
        headSpec.retrieve()                  >> respSpec
        respSpec.bodyToMono(BookingResponse) >> Mono.error(new RuntimeException("upstream 500"))

        when:
        client.getBooking(1)

        then: "BookingApiException is thrown carrying the configured error message"
        def ex = thrown(BookingApiException)
        ex.message == INJECTED_MESSAGE
    }

    def "getBooking should wrap the original cause inside BookingApiException on failure"() {
        given: "the Mono emits a specific cause"
        def cause = new RuntimeException("network timeout")
        webClient.get()                      >> uriSpec
        uriSpec.uri(*_)                      >> headSpec
        headSpec.retrieve()                  >> respSpec
        respSpec.bodyToMono(BookingResponse) >> Mono.error(cause)

        when:
        client.getBooking(99)

        then: "the original exception is preserved as the cause"
        def ex = thrown(BookingApiException)
        ex.cause == cause
    }

    def "getBooking should throw BookingApiException even when retrieve() itself throws synchronously"() {
        given: "retrieve() throws before a Mono is ever returned"
        webClient.get()  >> uriSpec
        uriSpec.uri(*_)  >> headSpec
        headSpec.retrieve() >> { throw new RuntimeException("connection refused") }

        when:
        client.getBooking(7)

        then:
        def ex = thrown(BookingApiException)
        ex.message == INJECTED_MESSAGE
    }

    def "getBooking should throw BookingApiException with the injected message when the external API returns HTTP 404"() {
        given: "the external Restful-Booker API responds with 404 Not Found"
        def notFound = WebClientResponseException.create(404, "Not Found", null, null, null)
        webClient.get()                      >> uriSpec
        uriSpec.uri(*_)                      >> headSpec
        headSpec.retrieve()                  >> respSpec
        respSpec.bodyToMono(BookingResponse) >> Mono.error(notFound)

        when:
        client.getBooking(999)

        then: "the 404 is caught and wrapped — the configured error message is used, and the original exception is the cause"
        def ex = thrown(BookingApiException)
        ex.message == INJECTED_MESSAGE
        ex.cause   == notFound
    }

    def "getBooking should throw BookingApiException with the injected message when the external API returns HTTP 500"() {
        given: "the external Restful-Booker API responds with 500 Internal Server Error"
        def serverError = WebClientResponseException.create(500, "Internal Server Error", null, null, null)
        webClient.get()                      >> uriSpec
        uriSpec.uri(*_)                      >> headSpec
        headSpec.retrieve()                  >> respSpec
        respSpec.bodyToMono(BookingResponse) >> Mono.error(serverError)

        when:
        client.getBooking(1)

        then: "the 500 is caught and wrapped — the configured error message is used, and the original exception is the cause"
        def ex = thrown(BookingApiException)
        ex.message == INJECTED_MESSAGE
        ex.cause   == serverError
    }
}

package com.example.transaction.client.impl

import com.example.transaction.dto.TransactionResponseDto
import org.springframework.web.reactive.function.client.WebClient
import reactor.core.publisher.Mono
import spock.lang.Specification

class WebClientTransactionClientSpec extends Specification {

    // Mock the entire WebClient fluent chain
    WebClient.Builder webClientBuilder = Mock()
    WebClient webClient = Mock()
    WebClient.RequestHeadersUriSpec requestUriSpec = Mock()
    WebClient.RequestHeadersSpec requestHeadersSpec = Mock()
    WebClient.ResponseSpec responseSpec = Mock()

    WebClientTransactionClient client

    def setup() {
        // Wire builder → webClient so the constructor call works
        webClientBuilder.build() >> webClient

        client = new WebClientTransactionClient(webClientBuilder)

        // Inject @Value fields via Groovy's direct field access
        client.@baseUrl = "http://serviex.local"
        client.@transactionsPath = "/transactions"
    }

    def "getTransaction should call WebClient and return the mapped response"() {
        given: "the WebClient chain returns a valid DTO"
        def expected = new TransactionResponseDto(500, "TechStore", "EUR", [])
        webClient.get() >> requestUriSpec
        requestUriSpec.uri(*_) >> requestHeadersSpec
        requestHeadersSpec.retrieve() >> responseSpec
        responseSpec.bodyToMono(TransactionResponseDto) >> Mono.just(expected)

        when: "getTransaction is called"
        def result = client.getTransaction("TX-42")

        then: "the response from the chain is returned"
        result == expected
    }

    def "getTransaction should build the URI from baseUrl, transactionsPath and the given id"() {
        given: "stub the remainder of the WebClient chain (retrieve + body)"
        def dto = new TransactionResponseDto(0, "", "", [])
        webClient.get() >> requestUriSpec
        requestHeadersSpec.retrieve() >> responseSpec
        responseSpec.bodyToMono(TransactionResponseDto) >> Mono.just(dto)

        when: "getTransaction is called with a specific id"
        client.getTransaction("TX-99")

        then: "uri is called exactly once with the correct template and the id as varargs"
        1 * requestUriSpec.uri("http://serviex.local/transactions/{id}", _ as Object[]) >> requestHeadersSpec
    }
}

package com.example.transaction.client.impl
import com.example.transaction.dto.TransactionResponseDto import org.springframework.web.reactive.function.client.WebClient import org.springframework.web.reactive.function.client.WebClientResponseException import reactor.core.publisher.Mono import spock.lang.Specification
class WebClientTransactionClientSpec extends Specification {
// Mock the entire WebClient fluent chain WebClient.Builder webClientBuilder = Mock() WebClient webClient = Mock() WebClient.RequestHeadersUriSpec requestUriSpec = Mock() WebClient.RequestHeadersSpec requestHeadersSpec = Mock() WebClient.ResponseSpec responseSpec = Mock()
WebClientTransactionClient client
def setup() { // Wire builder → webClient so the constructor call works webClientBuilder.build() >> webClient
client = new WebClientTransactionClient(webClientBuilder)
// Inject @Value fields via Groovy's direct field access client.@baseUrl = "http://serviex.local" client.@transactionsPath = "/transactions" }
def "getTransaction should call WebClient and return the mapped response"() { given: "the WebClient chain returns a valid DTO" def expected = new TransactionResponseDto(500, "TechStore", "EUR", []) webClient.get() >> requestUriSpec requestUriSpec.uri(*_) >> requestHeadersSpec requestHeadersSpec.retrieve() >> responseSpec responseSpec.bodyToMono(TransactionResponseDto) >> Mono.just(expected)
when: "getTransaction is called" def result = client.getTransaction("TX-42")
then: "the response from the chain is returned" result == expected }
def "getTransaction should build the URI from baseUrl, transactionsPath and the given id"() { given: "stub the remainder of the WebClient chain (retrieve + body)" def dto = new TransactionResponseDto(0, "", "", []) webClient.get() >> requestUriSpec requestHeadersSpec.retrieve() >> responseSpec responseSpec.bodyToMono(TransactionResponseDto) >> Mono.just(dto)
when: "getTransaction is called with a specific id" client.getTransaction("TX-99")
then: "uri is called exactly once with the correct template and the id as varargs" 1 * requestUriSpec.uri("http://serviex.local/transactions/{id}", _ as Object[]) >> requestHeadersSpec }
// ─── Error handling ────────────────────────────────────────────────────────
def "getTransaction should propagate RuntimeException when the Mono emits an error"() { given: "the Mono signals a generic upstream failure" webClient.get() >> requestUriSpec requestUriSpec.uri(*_) >> requestHeadersSpec requestHeadersSpec.retrieve() >> responseSpec responseSpec.bodyToMono(TransactionResponseDto) >> Mono.error(new RuntimeException("upstream failure"))
when: client.getTransaction("TX-ERR")
then: "the exception propagates unmodified — the client layer does not catch or wrap it" thrown(RuntimeException) }
def "getTransaction should propagate WebClientResponseException.Conflict for 409 responses so GlobalExceptionHandler can remap it to HTTP 500"() { given: "Serviex returns a 409 Conflict" def conflict = WebClientResponseException.create(409, "Conflict", null, null, null) webClient.get() >> requestUriSpec requestUriSpec.uri(*_) >> requestHeadersSpec requestHeadersSpec.retrieve() >> responseSpec responseSpec.bodyToMono(TransactionResponseDto) >> Mono.error(conflict)
when: client.getTransaction("TX-409")
then: "WebClientResponseException.Conflict propagates so the @ControllerAdvice can intercept it" def ex = thrown(WebClientResponseException.Conflict) ex.rawStatusCode == 409 }
def "getTransaction should propagate exception when retrieve() itself throws synchronously before returning a Mono"() { given: "retrieve() throws synchronously — no Mono is ever returned" webClient.get() >> requestUriSpec requestUriSpec.uri(*_) >> requestHeadersSpec requestHeadersSpec.retrieve() >> { throw new RuntimeException("connection refused") }
when: client.getTransaction("TX-DOWN")
then: "the synchronous exception propagates without being wrapped" thrown(RuntimeException) } }

package com.example.transaction.controller
import com.example.transaction.dto.TransactionResponseDto import com.example.transaction.service.TransactionService import org.springframework.http.MediaType import org.springframework.test.web.servlet.MockMvc import org.springframework.test.web.servlet.setup.MockMvcBuilders import spock.lang.Specification
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status
class TransactionControllerSpec extends Specification {
TransactionService transactionService = Mock() MockMvc mockMvc
def setup() { mockMvc = MockMvcBuilders .standaloneSetup(new TransactionController(transactionService)) .build() }
def "getTransaction should return HTTP 200 and correct transaction body for a valid id"() { given: "the service returns a populated TransactionResponseDto" def dto = new TransactionResponseDto(150, "MainStore", "USD", []) transactionService.getTransaction("TXN-01") >> dto
when: "the client calls GET /getTrx/TXN-01" def result = mockMvc.perform( get("/getTrx/TXN-01").accept(MediaType.APPLICATION_JSON))
then: "the response is 200 OK with the correct JSON fields" result.andExpect(status().isOk()) .andExpect(jsonPath('$.amount').value(150)) .andExpect(jsonPath('$.store').value("MainStore")) .andExpect(jsonPath('$.currency').value("USD")) }
def "getTransaction should delegate exactly once to transactionService with the path variable id"() { given: "the service returns any dto" def dto = new TransactionResponseDto(0, "S", "EUR", []) transactionService.getTransaction("ABC-99") >> dto
when: "the controller handles the request" mockMvc.perform(get("/getTrx/ABC-99"))
then: "service.getTransaction is called exactly once with the correct id" 1 * transactionService.getTransaction("ABC-99") } }

package com.example.transaction.controller
import com.example.transaction.dto.TransactionResponseDto import com.example.transaction.exception.GlobalExceptionHandler import com.example.transaction.service.TransactionService import org.springframework.http.MediaType import org.springframework.test.web.servlet.MockMvc import org.springframework.test.web.servlet.setup.MockMvcBuilders import org.springframework.web.reactive.function.client.WebClientResponseException import org.springframework.web.util.NestedServletException import spock.lang.Specification
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status
class TransactionControllerSpec extends Specification {
TransactionService transactionService = Mock() MockMvc mockMvc
def setup() { mockMvc = MockMvcBuilders .standaloneSetup(new TransactionController(transactionService)) .build() }
def "getTransaction should return HTTP 200 and correct transaction body for a valid id"() { given: "the service returns a populated TransactionResponseDto" def dto = new TransactionResponseDto(150, "MainStore", "USD", []) transactionService.getTransaction("TXN-01") >> dto
when: "the client calls GET /getTrx/TXN-01" def result = mockMvc.perform( get("/getTrx/TXN-01").accept(MediaType.APPLICATION_JSON))
then: "the response is 200 OK with the correct JSON fields" result.andExpect(status().isOk()) .andExpect(jsonPath('$.amount').value(150)) .andExpect(jsonPath('$.store').value("MainStore")) .andExpect(jsonPath('$.currency').value("USD")) }
def "getTransaction should delegate exactly once to transactionService with the path variable id"() { given: "the service returns any dto" def dto = new TransactionResponseDto(0, "S", "EUR", []) transactionService.getTransaction("ABC-99") >> dto
when: "the controller handles the request" mockMvc.perform(get("/getTrx/ABC-99"))
then: "service.getTransaction is called exactly once with the correct id" 1 * transactionService.getTransaction("ABC-99") }
// ─── Error handling ────────────────────────────────────────────────────────
def "getTransaction should return HTTP 500 with configured error body when service surfaces a WebClientResponseException.Conflict"() { given: "a GlobalExceptionHandler wired with known error values" def handler = new GlobalExceptionHandler() handler.@errorCode = "SERVIEX_CONFLICT" handler.@errorValue = 500 def mvc = MockMvcBuilders .standaloneSetup(new TransactionController(transactionService)) .setControllerAdvice(handler) .build() and: "the service propagates a 409 Conflict from Serviex" transactionService.getTransaction("TXN-409") >> { throw WebClientResponseException.create(409, "Conflict", null, null, null) }
when: def result = mvc.perform(get("/getTrx/TXN-409").accept(MediaType.APPLICATION_JSON))
then: "GlobalExceptionHandler translates it to HTTP 500 with the configured code and Error fields" result.andExpect(status().isInternalServerError()) .andExpect(jsonPath('$.code').value("SERVIEX_CONFLICT")) .andExpect(jsonPath('$.Error').value(500)) }
def "getTransaction should propagate an unhandled RuntimeException as NestedServletException when no matching handler exists"() { given: "the service throws a generic exception not covered by GlobalExceptionHandler" transactionService.getTransaction("TXN-BOOM") >> { throw new RuntimeException("unexpected internal error") }
when: "MockMvc dispatches the request — no ControllerAdvice is installed in this setup" mockMvc.perform(get("/getTrx/TXN-BOOM"))
then: "MockMvc wraps the unhandled exception in a NestedServletException and re-throws it" def ex = thrown(NestedServletException) ex.cause instanceof RuntimeException ex.cause.message == "unexpected internal error" } }

package com.example.transaction.service.impl

import com.example.transaction.client.BookingClient
import com.example.transaction.dto.BookingDates
import com.example.transaction.dto.BookingResponse
import com.example.transaction.entity.BookingEntity
import com.example.transaction.exception.BookingApiException
import com.example.transaction.repository.BookingRepository
import spock.lang.Specification

class BookingServiceImplSpec extends Specification {

    BookingClient      bookingClient      = Mock()
    BookingRepository  bookingRepository  = Mock()
    BookingServiceImpl service

    def setup() {
        service = new BookingServiceImpl(bookingClient, bookingRepository)
    }

    // ─── Delegation & return value ─────────────────────────────────────────────

    def "getBooking should delegate to bookingClient and return the BookingResponse"() {
        given: "a fully populated BookingResponse"
        def dates    = new BookingDates("2018-01-01", "2019-01-01")
        def expected = new BookingResponse("Josh", "Allen", 111, true, dates, "super bowls")

        when:
        def result = service.getBooking(1)

        then: "bookingClient is called exactly once with the correct id"
        1 * bookingClient.getBooking(1) >> expected
        and: "the original BookingResponse is returned to the caller"
        result == expected
    }

    def "getBooking should pass the id through to bookingClient unchanged"() {
        given:
        def dto = new BookingResponse("A", "B", 0, false, new BookingDates("", ""), "")

        when:
        service.getBooking(99)

        then:
        1 * bookingClient.getBooking(99) >> dto
    }

    // ─── MongoDB save logic ────────────────────────────────────────────────────

    def "getBooking should save a BookingEntity embedding the full BookingResponse"() {
        given: "the client returns a booking"
        def dates    = new BookingDates("2018-01-01", "2019-01-01")
        def response = new BookingResponse("Josh", "Allen", 111, true, dates, "super bowls")
        bookingClient.getBooking(7) >> response

        when:
        service.getBooking(7)

        then: "repository.save is called once with an entity containing the full BookingResponse"
        1 * bookingRepository.save({ BookingEntity e ->
            e.bookingData == response &&
            e.savedAt     != null
        })
    }

    def "getBooking should still return BookingResponse even when repository.save throws"() {
        given: "the client returns a booking but the database is down"
        def dates    = new BookingDates("2018-01-01", "2019-01-01")
        def response = new BookingResponse("Josh", "Allen", 111, true, dates, "super bowls")
        bookingClient.getBooking(3) >> response
        bookingRepository.save(_) >> { throw new RuntimeException("MongoDB unreachable") }

        when: "getBooking is called despite the DB being down"
        def result = service.getBooking(3)

        then: "no exception propagates — the API flow continues"
        noExceptionThrown()
        and: "the original BookingResponse is still returned"
        result == response
    }

    def "getBooking should not propagate any exception from repository.save"() {
        given:
        def response = new BookingResponse("X", "Y", 0, false, new BookingDates("", ""), "")
        bookingClient.getBooking(10) >> response
        bookingRepository.save(_) >> { throw new RuntimeException("connection timeout") }

        when:
        service.getBooking(10)

        then:
        noExceptionThrown()
    }

    // ─── Error propagation from client ────────────────────────────────────────

    def "getBooking should propagate BookingApiException thrown by bookingClient"() {
        given: "the HTTP client fails"
        bookingClient.getBooking(1) >> { throw new BookingApiException("ketoKet") }

        when:
        service.getBooking(1)

        then: "exception bubbles up before any DB save is attempted"
        def ex = thrown(BookingApiException)
        ex.message == "ketoKet"
        and: "repository is never touched"
        0 * bookingRepository.save(_)
    }

    def "getBooking should not swallow RuntimeException thrown by bookingClient"() {
        given:
        bookingClient.getBooking(5) >> { throw new RuntimeException("unexpected") }

        when:
        service.getBooking(5)

        then:
        thrown(RuntimeException)
        and:
        0 * bookingRepository.save(_)
    }
}

package com.example.transaction.service.impl

import com.example.transaction.client.BookingClient
import com.example.transaction.dto.BookingDates
import com.example.transaction.dto.BookingResponse
import com.example.transaction.entity.BookingEntity
import com.example.transaction.exception.BookingApiException
import com.example.transaction.repository.BookingRepository
import spock.lang.Specification

class BookingServiceImplSpec extends Specification {

    BookingClient      bookingClient      = Mock()
    BookingRepository  bookingRepository  = Mock()
    BookingServiceImpl service

    def setup() {
        service = new BookingServiceImpl(bookingClient, bookingRepository)
    }

    // ─── Delegation & return value ─────────────────────────────────────────────

    def "getBooking should delegate to bookingClient and return the BookingResponse"() {
        given: "a fully populated BookingResponse"
        def dates    = new BookingDates("2018-01-01", "2019-01-01")
        def expected = new BookingResponse("Josh", "Allen", 111, true, dates, "super bowls")

        when:
        def result = service.getBooking(1)

        then: "bookingClient is called exactly once with the correct id"
        1 * bookingClient.getBooking(1) >> expected
        and: "the original BookingResponse is returned to the caller"
        result == expected
    }

    def "getBooking should pass the id through to bookingClient unchanged"() {
        given:
        def dto = new BookingResponse("A", "B", 0, false, new BookingDates("", ""), "")

        when:
        service.getBooking(99)

        then:
        1 * bookingClient.getBooking(99) >> dto
    }

    // ─── MongoDB save logic ────────────────────────────────────────────────────

    def "getBooking should save a BookingEntity embedding the full BookingResponse"() {
        given: "the client returns a booking"
        def dates    = new BookingDates("2018-01-01", "2019-01-01")
        def response = new BookingResponse("Josh", "Allen", 111, true, dates, "super bowls")
        bookingClient.getBooking(7) >> response

        when:
        service.getBooking(7)

        then: "repository.save is called once with an entity containing the full BookingResponse"
        1 * bookingRepository.save({ BookingEntity e ->
            e.bookingData == response &&
            e.savedAt     != null
        })
    }

    def "getBooking should still return BookingResponse even when repository.save throws"() {
        given: "the client returns a booking but the database is down"
        def dates    = new BookingDates("2018-01-01", "2019-01-01")
        def response = new BookingResponse("Josh", "Allen", 111, true, dates, "super bowls")
        bookingClient.getBooking(3) >> response
        bookingRepository.save(_) >> { throw new RuntimeException("MongoDB unreachable") }

        when: "getBooking is called despite the DB being down"
        def result = service.getBooking(3)

        then: "no exception propagates — the API flow continues"
        noExceptionThrown()
        and: "the original BookingResponse is still returned"
        result == response
    }

    def "getBooking should not propagate any exception from repository.save"() {
        given:
        def response = new BookingResponse("X", "Y", 0, false, new BookingDates("", ""), "")
        bookingClient.getBooking(10) >> response
        bookingRepository.save(_) >> { throw new RuntimeException("connection timeout") }

        when:
        service.getBooking(10)

        then:
        noExceptionThrown()
    }

    // ─── Error propagation from client ────────────────────────────────────────

    def "getBooking should propagate BookingApiException thrown by bookingClient"() {
        given: "the HTTP client fails"
        bookingClient.getBooking(1) >> { throw new BookingApiException("ketoKet") }

        when:
        service.getBooking(1)

        then: "exception bubbles up before any DB save is attempted"
        def ex = thrown(BookingApiException)
        ex.message == "ketoKet"
        and: "repository is never touched"
        0 * bookingRepository.save(_)
    }

    def "getBooking should not swallow RuntimeException thrown by bookingClient"() {
        given:
        bookingClient.getBooking(5) >> { throw new RuntimeException("unexpected") }

        when:
        service.getBooking(5)

        then:
        thrown(RuntimeException)
        and:
        0 * bookingRepository.save(_)
    }

    // ─── Additional error-handling edge cases ─────────────────────────────────

    def "getBooking should swallow specific database exceptions such as IllegalStateException from repository and still return the response"() {
        given: "the DB throws a schema-level error"
        def response = new BookingResponse("A", "B", 0, false, new BookingDates("", ""), "")
        bookingClient.getBooking(20) >> response
        bookingRepository.save(_)   >> { throw new IllegalStateException("DB schema mismatch") }

        when:
        def result = service.getBooking(20)

        then: "the IllegalStateException is silently swallowed — API flow continues"
        noExceptionThrown()
        and:
        result == response
    }

    def "getBooking should preserve the full cause chain of a BookingApiException thrown by bookingClient"() {
        given: "the HTTP client wraps a root-cause exception"
        def rootCause = new RuntimeException("connection refused")
        def apiEx     = new BookingApiException("ketoKet", rootCause)
        bookingClient.getBooking(2) >> { throw apiEx }

        when:
        service.getBooking(2)

        then: "the BookingApiException propagates with message and cause intact for diagnostics"
        def ex = thrown(BookingApiException)
        ex.message == "ketoKet"
        ex.cause   == rootCause
        and: "repository is never touched because the client failed before any response was obtained"
        0 * bookingRepository.save(_)
    }
}
